mapper.select:
SELECT COUNT(*)
FROM tasks
WHERE username = #{username}

SELECT id, username, title, content, name, start_date AS startDate, end_date AS endDate, created_at AS createdAt, updated_at AS updatedAt FROM tasks WHERE username = #{username}
AND title LIKE CONCAT('%', #{searchTitle}, '%')
AND start_date BETWEEN #{searchStartDate} AND #{searchEndDate}
AND start_date >= #{searchStartDate}
AND start_date <= #{searchEndDate}
ORDER BY id DESC

mapper.delete:
DELETE FROM tasks
WHERE id = #{id}
  AND username = #{username}
